import { useEffect, useRef } from 'react';

import OpenFin from '@openfin/core';

import { subscribePopupChannelAction } from './channelLifecycle';

interface UsePopupChannelArgs<T> {
    createChannel: () => Promise<OpenFin.ChannelProvider>;
    actionName: string;
    handler: (event: T) => Promise<void>;
}

export const usePopupChannel = <T>({ createChannel, actionName, handler }: UsePopupChannelArgs<T>) => {
    const channelRef = useRef<OpenFin.ChannelProvider | null>(null);
    const handlerRef = useRef(handler);
    handlerRef.current = handler;

    useEffect(() => {
        const subscription = subscribePopupChannelAction(createChannel, actionName, async (event: T) =>
            handlerRef.current(event)
        );

        subscription.channelPromise
            .then((channel) => {
                channelRef.current = channel;
            })
            .catch((error) => {
                console.error('Error setting up channel:', error);
            });

        return () => {
            channelRef.current = null;
            subscription.unsubscribe();
        };
    }, [createChannel, actionName]);

    return channelRef;
};
